using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service;

    public OrderServiceTests()
    {
        _service = new OrderService();
    }

    private static List<OrderItem> CreateItems(int count = 1) =>
        Enumerable.Range(1, count)
            .Select(i => new OrderItem
            {
                ProductName = $"Product {i}",
                Price = 10m * i,
                Quantity = i
            })
            .ToList();

    [TestMethod]
    public void CreateOrder_WithValidInputs_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 25m, Quantity = 2 },
            new() { ProductName = "Gadget", Price = 10m, Quantity = 3 },
        };

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.IsNotNull(order);
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.AreEqual(80m, order.Total); // 25*2 + 10*3
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithValidInputs_AssignsIdAndTimestamp()
    {
        // Arrange
        var items = CreateItems();
        var before = DateTime.UtcNow;

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.IsNotNull(order.Id);
        Assert.IsGreaterThan(before.AddSeconds(-1), order.CreatedAt);
    }

    [TestMethod]
    public void CreateOrder_NullCustomerId_ThrowsArgumentNullException()
    {
        var items = CreateItems();

        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _service.CreateOrder(null!, items));

        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_NullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _service.CreateOrder("cust-1", null!));

        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_EmptyItems_ThrowsInvalidOperationException()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _service.CreateOrder("cust-1", []));

        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    [TestMethod]
    public void GetOrder_ExistingOrder_ReturnsOrder()
    {
        // Arrange
        var items = CreateItems();
        var created = _service.CreateOrder("cust-1", items);

        // Act
        var retrieved = _service.GetOrder(created.Id);

        // Assert
        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_NonExistentId_ReturnsNull()
    {
        var result = _service.GetOrder("does-not-exist");

        Assert.IsNull(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_MultipleOrders_ReturnsOnlyMatchingCustomer()
    {
        // Arrange
        _service.CreateOrder("cust-A", CreateItems());
        _service.CreateOrder("cust-A", CreateItems(2));
        _service.CreateOrder("cust-B", CreateItems());

        // Act
        var results = _service.GetOrdersByCustomer("cust-A");

        // Assert
        Assert.HasCount(2, results);
    }

    [TestMethod]
    public void GetOrdersByCustomer_NoOrders_ReturnsEmptyList()
    {
        var results = _service.GetOrdersByCustomer("nobody");

        Assert.IsEmpty(results);
    }

    [TestMethod]
    [DataRow(1, 10, 1, 10)]
    [DataRow(5, 3, 2, 30)]
    [DataRow(1, 100, 10, 1000)]
    public void CreateOrder_SingleItem_TotalIsCorrect(
        int itemCount, decimal price, int quantity, decimal expectedTotal)
    {
        // Arrange - itemCount items all at same price/quantity
        var items = Enumerable.Range(0, itemCount)
            .Select(_ => new OrderItem { ProductName = "X", Price = price, Quantity = quantity })
            .ToList();

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual(expectedTotal, order.Total);
    }
}

